const sqlite3 = require('sqlite3').verbose();

const taskDescrizione = $input.first().json.task_descrizione || '';
const nuovaScadenza = $input.first().json.nuova_scadenza || null;

if (!taskDescrizione) {
  return [{ json: { output: 'Parametro task_descrizione mancante.' } }];
}
if (!nuovaScadenza) {
  return [{ json: { output: 'Parametro nuova_scadenza mancante (formato YYYY-MM-DD).' } }];
}

const tasks = await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');
  db.all(
    `SELECT id, descrizione, scadenza FROM task 
     WHERE stato = 'aperto' 
     AND LOWER(descrizione) LIKE LOWER(?)
     ORDER BY creato_il DESC LIMIT 5`,
    [`%${taskDescrizione}%`],
    function(err, rows) {
      db.close();
      if (err) reject(err);
      else resolve(rows);
    }
  );
});

if (tasks.length === 0) {
  return [{ json: { output: `Nessun task aperto trovato con descrizione simile a "${taskDescrizione}".` } }];
}

const task = tasks[0];
const vecchiaScadenza = task.scadenza ? task.scadenza.slice(0,10) : 'nessuna';
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
const nowISO = now.toISOString().slice(0, 19).replace('T', ' ');

await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');
  db.run(
    `UPDATE task SET 
      scadenza = ?,
      next_followup_at = ?,
      reminder_count = 0,
      updated_at = ?
     WHERE id = ?`,
    [nuovaScadenza, nuovaScadenza + ' 09:00:00', nowISO, task.id],
    function(err) {
      db.close();
      if (err) reject(err);
      else resolve();
    }
  );
});

return [{ json: { 
  output: `Task ID ${task.id} "${task.descrizione}" posticipato da ${vecchiaScadenza} a ${nuovaScadenza}. Contatore solleciti azzerato.`
} }];
